import pages as PG
from pages import *
from fig2 import *
from fig import strip,svg
P_=[('overview','Pitṛ Pakṣa','The Fortnight of the Ancestors'),('shraddha-tarpana','Śrāddha and Tarpaṇa','What the Rites Mean'),('mahalaya-amavasya','Mahālaya Amāvāsyā','The New Moon for All Ancestors'),('places','The Places of Śrāddha','Gayā, Kāśī, Prayāga and Śrīraṅgapaṭṇa'),('after-death','What Happens After Death','The Tradition’s Map, and the Garuḍa Purāṇa')]
PG.configure('/festivals/pitru-paksha/',P_,'navy','Pitṛ Pakṣa','Lord','Pitṛ Pakṣa')
PG.OUT='outx/pitru-paksha/'
import pages
L=pages.link
EL=lambda: person('#8a8a8a')
i=0
COV=covart('A family seated by a river offering water with sesame from cupped hands, crows on a branch, and faint figures of elders above in a soft light',river(440,160)+g(160,170,1,person('#f4f1ea',seat=True))+g(220,170,1,person('#f4f1ea',seat=True))+g(330,120,.9,crow())+g(370,120,.9,crow())+''.join(g(x,70,.6,EL()) for x in (110,160,210)))
pp=[foreword(i,['Before the Goddess comes for Navarātri, the dark fortnight before it belongs to the ancestors. <b>Pitṛ Pakṣa</b>, “the fortnight of the forefathers”, also called <b>Mahālaya Pakṣa</b>, is when Hindu families remember their departed parents and forebears with offerings of water, sesame and food.','This 5-part series explains the fortnight, what the rites mean, the great new moon that closes it, the holy places of śrāddha, and the tradition’s picture of life after death. It describes; it is not a priest’s manual.'],[('z','Is it a sad time?'),('b','A serious time, not a gloomy one. It is about gratitude: we exist because they did.')]),
 glance([('Name','Pitṛ Pakṣa, Mahālaya Pakṣa, Apara Pakṣa'),('When','The dark fortnight of Bhādrapada (amānta) / Āśvina (pūrṇimānta), before Navarātri'),('Who is honoured','Departed parents, grandparents and forebears (pitṛs)'),('Rites','Śrāddha (offering food), tarpaṇa (water with sesame), feeding crows, cows, the poor'),('Each day','The tithi on which a person died is their day in the fortnight'),('Closes with','Mahālaya Amāvāsyā, for all ancestors'),('Also','Indirā Ekādaśī falls in it')],svg(560,140,'Three generations of elders in a soft light above a lamp',g(280,130,1.5,lamp())+''.join(g(x,90,.7,EL()) for x in (180,280,380)))),
 reading('what','THE FORTNIGHT OF THE ANCESTORS','What Pitṛ Pakṣa is',svg(560,170,'A family tree with elders at the roots and children at the branches',g(280,165,2.3,tree('#5a8a3a'))+''.join(g(x,165,.6,EL()) for x in (200,240,320,360))+''.join(g(x,60,.5,child()) for x in (230,280,330))),['<b>The pitṛs.</b> In Hindu thought the <b>pitṛs</b>, the departed ancestors, live in their own world, the pitṛ-loka, and are nourished by the offerings of their descendants.','<b>The fortnight.</b> For fifteen days in the dark half of the lunar month before Navarātri, these offerings are made with special care. Each family usually performs śrāddha for a parent on the tithi (lunar day) of that parent’s death.','<b>The three debts.</b> Tradition speaks of three debts every person carries: to the gods, to the sages, and to the ancestors (<i>pitṛ-ṛṇa</i>). Śrāddha is how the third is honoured.','<b>Gratitude.</b> At its heart the fortnight is thanksgiving: remembering those whose lives made ours possible.'],[('z','Do the ancestors really get the food?'),('b','The tradition says the offering reaches them through the rite. Whatever one believes, the remembering is real.')],'Fifteen days to <b>remember and thank the ancestors</b>.'),
 story('karna','KARṆA AND THE GOLDEN FOOD','The story behind the fortnight',strip('Three panels: Karṇa giving gold to beggars; Karṇa in heaven surrounded by gold but hungry; Karṇa back on earth offering food and water',[panel([(person('#e0a800'),.9),(person('#8a6a4a'),.7)],'#fff3cf',140),panel([(person('#e0a800'),.8)]+[('<circle r="10" fill="#e0a800" stroke="#111"/>',1)],'#e9e3f5',140),panel([(person('#e0a800'),.8),(piNDa(),1)],'#cfe0b8',140)],['a giver of gold','hungry among gold','fifteen days on earth']),'A popular story explains why the fortnight exists.',['<b>Karṇa</b> of the Mahābhārata was famous for his generosity: he gave gold to anyone who asked.','When he died and reached heaven, he was offered gold and jewels to eat, but no food.','He asked Indra why. Indra told him: in life you gave gold, but never food or water to your ancestors.','Karṇa had not known who his ancestors were. He was allowed to return to earth for fifteen days to offer food and water in their memory.','Those fifteen days, the story says, became <b>Pitṛ Pakṣa</b>.'],[('z','So even Karṇa forgot?'),('b','He didn’t know his own family, as you know from the Mahābhārata. The story says: don’t let your ancestors go unremembered.')],'Gold is not food: <b>Karṇa returns to feed his ancestors</b>.'),
 reading('who','WHO IS REMEMBERED, AND WHEN','The tithis of the fortnight',svg(560,150,'Fifteen moon phases of the dark fortnight with a person marked on one',''.join(f'<circle cx="{30+k*35}" cy="70" r="13" fill="#fff8d0" stroke="#111" stroke-width="1.5"/><circle cx="{30+k*35+(k*1.8)}" cy="70" r="13" fill="#2a2a3a"/>' for k in range(15))+lab(280,120,'each parent is remembered on the tithi of their passing')),['<b>By tithi.</b> A parent who died on, say, the fifth lunar day is remembered on the fifth day of Pitṛ Pakṣa, whatever the calendar date.','<b>Special days.</b> Some days have special uses in many traditions: Navamī for mothers (Avidhavā Navamī), Caturdaśī for those who died violently or untimely, Dvādaśī for sannyāsins.','<b>When the day is unknown.</b> If the death tithi is not known, or for all ancestors together, śrāddha is done on <b>Mahālaya Amāvāsyā</b> ('+L(2,'Part 3')+').','<b>Who performs it.</b> Traditionally a son performs śrāddha; families today increasingly include daughters and other relatives. Customs differ by community.'],[('z','Can a daughter do it?'),('b','Many families now say yes, and several traditions allow it. Ask your family priest; practice is changing.')],'Each ancestor has <b>their own day</b> in the fortnight.'),
 reading('restraint','A TIME OF RESTRAINT','What families avoid',svg(560,150,'A calendar with crossed-out symbols for new purchases and celebrations',g(180,120,1.2,'<rect x="-40" y="-60" width="80" height="60" fill="#fff" stroke="#111" stroke-width="2"/>')+'<path d="M140 50 L220 110 M220 50 L140 110" stroke="#c0392b" stroke-width="5"/>'+g(400,130,1.4,lamp())),['<b>No new beginnings.</b> Many families avoid weddings, house-warmings, new purchases and starting ventures during the fortnight, considering it a time to look back, not forward.','<b>Simple food.</b> Some avoid non-vegetarian food, onion and garlic, and eat simply.','<b>Not inauspicious, but different.</b> The fortnight is not “bad luck”; it is set aside for a different purpose. Not everyone observes these restrictions.','<b>Then joy.</b> The fortnight ends, and the next day Navarātri begins.'],[('z','Why no shopping?'),('b','Tradition keeps this fortnight for the past. The new things wait for Navarātri and Dīpāvalī.')],'A fortnight <b>given to the past</b>, before the festivals.'),
 end(i,['<b>What.</b> Pitṛ Pakṣa: fifteen days for the ancestors.','<b>When.</b> The dark fortnight before Navarātri.','<b>Story.</b> Karṇa, hungry among gold, returned to feed his ancestors.','<b>Days.</b> Each ancestor on their death tithi; all on Mahālaya Amāvāsyā.','<b>Mood.</b> Gratitude and restraint.'],'Part 2 explains the rites themselves: what śrāddha and tarpaṇa are and what each element means.','Pitṛ Pakṣa'),
 sources([('Fortnight:','Wikipedia, “Pitru Paksha” (dates, tithis, Karṇa legend, customs), “Shraddha”.')],'the Karṇa story (popular, not in the critical Mahābhārata); who may perform śrāddha (customs vary).','Customs described in general; follow your family priest.')]
build(i,'PART 1 OF 5 · THE ANCESTORS · GRATITUDE',COV,'Water and sesame for those before us','What <b>Pitṛ Pakṣa</b> is, <b>Karṇa’s story</b>, who is remembered <b>on which day</b>, and why it is a time of restraint.','Pitṛ Pakṣa (Mahālaya Pakṣa) explained: the fortnight of the ancestors before Navarātri, the story of Karṇa, how each ancestor’s day is set by tithi, and the customs of restraint. Part 1 of the illustrated Pitṛ Pakṣa series.',pp)
# Part 2
i=1
COV=covart('Hands offering water mixed with black sesame through darbha grass, three rice balls on a leaf, and a crow waiting nearby',g(160,180,1.6,piNDa())+g(300,140,1.3,'<path d="M-20 0 q20 20 40 0 l-6 -20 h-28z" fill="#c98a5a" stroke="#111" stroke-width="2"/>'+''.join(f'<circle cx="{x}" cy="16" r="2" fill="#111"/>' for x in (-6,0,6)))+g(380,190,1.2,crow()))
pp=[foreword(i,['In '+L(0,'Part 1')+' we saw what Pitṛ Pakṣa is. Now the rites themselves: <b>śrāddha</b>, the offering made with faith (<i>śraddhā</i>), and <b>tarpaṇa</b>, the offering of water.','We explain what each element means and why it is used. The rites themselves are done with a priest or by those trained in them, following the family’s tradition (Ṛg-, Yajur- or Sāma-vedic, Smārta or Vaiṣṇava).'],[('z','Why so many details?'),('b','Each element carries a meaning. Knowing them turns a ritual into remembrance.')]),
 glance([('Śrāddha','An offering of food to the ancestors, made with faith; feeding brahmins/guests on their behalf'),('Tarpaṇa','Offering water with black sesame, through darbha grass'),('Piṇḍa','Rice balls offered for three generations'),('Black sesame','Said to be dear to the pitṛs'),('Darbha','Sacred kuśa grass, worn as a ring (pavitra)'),('Direction','South, the direction of Yama and the ancestors'),('Crows, cows, dogs','Portions set aside for them')],svg(560,140,'Darbha grass, sesame, a rice ball and water',g(100,120,1,'<path d="M-6 0 q-4 -40 4 -60 M0 0 q2 -40 -2 -60 M6 0 q4 -40 -4 -60" stroke="#5a8a3a" stroke-width="3" fill="none"/>')+g(220,120,1.5,'<circle r="18" fill="#2a2a3a"/>')+g(340,120,1.4,piNDa())+g(460,120,1.2,pot('#c9a24a')))),
 reading('shraddha','ŚRĀDDHA','An offering made with faith',svg(560,170,'Guests seated and served food on leaves on behalf of the ancestors',ground(560,170,150,'#e9d6c0')+''.join(g(x,150,.9,person(c,seat=True)) for x,c in [(160,'#f4f1ea'),(240,'#f4f1ea'),(320,'#f4f1ea')])+''.join(f'<ellipse cx="{x}" cy="160" rx="22" ry="6" fill="#5a8a3a" stroke="#111"/>' for x in (160,240,320))+g(440,150,1,person('#c0392b'))),['<b>The name.</b> <b>Śrāddha</b> comes from <i>śraddhā</i>, faith: an offering whose power lies in the faith with which it is made.','<b>Feeding on their behalf.</b> In the classic rite, invited brahmins (or other worthy guests) are fed as representatives of the ancestors, and their satisfaction is said to reach the pitṛs.','<b>Simple food.</b> The meal is pure vegetarian, often including foods the departed loved; customs differ by region.','<b>Giving.</b> Gifts of food, clothes and money to the needy are part of the rite.'],[('z','The guests eat for the ancestors?'),('b','That is the idea: feeding the living as a channel to the dead. Feeding the hungry is never wasted.')],'Food offered <b>with faith, through the living</b>.'),
 reading('tarpana','TARPAṆA','Water and sesame',svg(560,170,'A man standing in a river offering water from cupped hands with sesame seeds',river(560,120)+g(280,140,1.2,person('#f4f1ea'))+g(280,90,1,'<path d="M-20 0 q20 20 40 0" fill="#c98a5a" stroke="#111" stroke-width="2"/>')+'<path d="M290 100 q10 20 0 40" stroke="#8fb8de" stroke-width="3" fill="none"/>'),['<b>The offering of water.</b> <b>Tarpaṇa</b> means “satisfying”: water is poured from the hands, with black sesame and darbha grass, while the names of the ancestors are spoken.','<b>Sesame.</b> Black sesame (tila) is traditionally used only for the ancestors; it is said to be dear to them and to purify.','<b>Darbha.</b> A ring of sacred darbha (kuśa) grass, the <b>pavitra</b>, is worn on the finger, and the water flows over darbha blades.','<b>The sacred thread.</b> Those who wear the thread shift it to the right shoulder (prācīnāvīta) for rites to the ancestors, the reverse of rites for the gods.'],[('z','Why reverse everything?'),('b','Rites for the ancestors mirror rites for the gods: south instead of east, right shoulder instead of left. It marks them as a different world.')],'Water, sesame and darbha: <b>tarpaṇa</b>.'),
 reading('pinda','PIṆḌA AND THE THREE GENERATIONS','Rice balls for father, grandfather and great-grandfather',svg(560,160,'Three rice balls on a leaf, each labelled for a generation',g(280,130,2.2,piNDa())+lab(236,150,'father')+lab(280,150,'grandfather')+lab(324,150,'great-grandfather')),['<b>Piṇḍa.</b> Balls of cooked rice mixed with sesame, honey or ghee are offered on darbha grass.','<b>Three generations.</b> Traditionally three piṇḍas honour the father, grandfather and great-grandfather (with parallel offerings for the maternal line in many traditions).','<b>Beyond three.</b> Older generations are believed to have moved on; the rite looks after the three nearest.','<b>After the rite.</b> Piṇḍas are given to crows or cows, or placed in water.'],[('z','Why only three generations?'),('b','In the tradition, the nearest three are still “pitṛs” in need; beyond them, the ancestors are said to have gone on.')],'Three rice balls, <b>three generations</b>.'),
 reading('crows','CROWS, COWS AND DOGS','Feeding all beings',svg(560,160,'A crow, a cow and a dog each with a small portion of food',g(140,130,1.6,crow())+g(290,140,1,beast('bull','#f4f1ea'))+g(450,140,.8,beast('donkey','#c98a5a'))),['<b>Crows.</b> Before anyone eats, a portion is placed for crows. In popular belief the ancestors come as crows; if a crow eats quickly, the offering is said to be accepted.','<b>Cows and dogs.</b> Portions are also set aside for a cow and a dog, and often for ants.','<b>All beings.</b> The custom grows from the old idea of <i>bhūta-yajña</i>: feeding all creatures is part of every household’s duty.','<b>Patience.</b> Families sometimes wait a long time for a crow to come. The waiting itself becomes part of the remembering.'],[('z','The ancestors are crows?'),('b','A popular belief, beautifully symbolic. Scriptures speak of crows as messengers; many families simply see them as guests.')],'Crows, cows and dogs: <b>feeding every being</b>.'),
 end(i,['<b>Śrāddha.</b> Food offered with faith, through invited guests.','<b>Tarpaṇa.</b> Water with sesame through darbha.','<b>Piṇḍa.</b> Rice balls for three generations.','<b>Reversed.</b> South, right shoulder: the ancestors’ world.','<b>All beings.</b> Crows, cows and dogs fed first.'],'Part 3 is Mahālaya Amāvāsyā, the new moon for all ancestors, and in Bengal the dawn of Durgā Pūjā.','Śrāddha and Tarpaṇa'),
 sources([('Rites:','Wikipedia, “Shraddha”, “Tarpana”, “Pinda”; Garuḍa Purāṇa and Gṛhya Sūtra traditions as commonly summarised.')],'regional variation in items, number of piṇḍas and who is fed; the crow belief (popular).','This is a description, not a manual; follow your family priest.')]
build(i,'PART 2 OF 5 · ŚRĀDDHA · TARPAṆA · PIṆḌA',COV,'Water, sesame and rice','<b>Śrāddha</b>, <b>tarpaṇa</b> and the <b>piṇḍa</b> explained element by element, and why crows, cows and dogs are fed.','Śrāddha and tarpaṇa explained: offerings of food with faith, water with black sesame and darbha grass, piṇḍa for three generations, the reversed sacred thread and direction, and feeding crows, cows and dogs. Part 2 of the illustrated Pitṛ Pakṣa series.',pp)
# Part 3
i=2
COV=covart('A dark new-moon sky, a river with people offering water, and at the right the first light of dawn over a Bengali clay goddess image being painted',
 '<rect width="440" height="196" fill="#2a2a3a"/>'+river(440,150)+''.join(g(x,170,.9,person('#f4f1ea')) for x in (90,140,190))+g(350,170,.9,devi(items=('trident','sword','lotus','abhaya'))))
pp=[foreword(i,['The fortnight closes with its greatest day: <b>Mahālaya Amāvāsyā</b>, also called <b>Sarva Pitṛ Amāvāsyā</b>, the new moon for <i>all</i> ancestors. Whoever was forgotten, or whose day is not known, is remembered today.','The next day the Goddess arrives: Navarātri begins. In Bengal, Mahālaya dawn is also the moment Durgā is invited, with the famous recitation of the Caṇḍī. Our <a href="/festivals/navaratri/">Navarātri series</a> takes it from there.'],[('z','The ancestors leave and the Goddess comes?'),('b','That’s the beautiful turn: from the dark new moon of remembrance to the bright nights of the Mother.')]),
 glance([('Name','Mahālaya Amāvāsyā, Sarva Pitṛ Amāvāsyā, Pitṛ Mokṣa Amāvāsyā'),('When','The new moon closing Pitṛ Pakṣa, the day before Navarātri'),('For','All ancestors, especially those whose death day is unknown'),('Rites','Tarpaṇa and śrāddha, river bathing, feeding the poor'),('Bengal','Mahālaya: dawn invocation of Durgā; the eyes of the images painted'),('Next day','Ghaṭasthāpana: Navarātri begins')],svg(560,140,'A dark moon on the left and a bright lamp for the Goddess on the right',g(160,80,1.6,'<circle r="24" fill="#2a2a3a" stroke="#111" stroke-width="2"/>')+'<path d="M220 80 h120" stroke="#111" stroke-width="3"/><path d="M340 80 l-10 -6 v12z" fill="#111"/>'+g(420,110,1.6,lamp()))),
 reading('all','THE NEW MOON FOR ALL','Sarva Pitṛ Amāvāsyā',svg(560,170,'Many rows of faint figures, a whole family line, above people offering water',''.join(g(80+k*50,60,.5,EL()) for k in range(9))+river(560,120)+g(280,150,1,person('#f4f1ea'))),['<b>Everyone at once.</b> On this new moon, families offer tarpaṇa and śrāddha for all their ancestors together: those whose death days are known, those whose are not, those who died without descendants, even friends and teachers.','<b>Forgetting forgiven.</b> If someone missed their parent’s day in the fortnight, this day makes up for it.','<b>Rivers and tanks.</b> Large crowds gather at rivers, tanks and sacred places to offer water.','<b>Feeding.</b> Feeding the poor and giving food grains is especially praised.'],[('z','Even people who weren’t family?'),('b','Many offer a handful of water “for all who have no one to remember them”. That is one of the kindest rites in the tradition.')],'One day <b>for every ancestor</b>, known and unknown.'),
 reading('bengal','MAHĀLAYA IN BENGAL','The Goddess is invited',svg(560,180,'An artist painting the eyes of a clay Durgā image in a workshop at dawn',g(300,170,1.3,devi(sari='#c0392b',items=('trident','sword','discus','lotus','bow','conch')))+g(140,170,1,person('#1d6fb8',seat=True))+g(175,110,.6,'<path d="M0 0 l30 -10" stroke="#8a5a2a" stroke-width="3"/>')),['<b>Before dawn.</b> In Bengal, Mahālaya begins long before sunrise with the recitation of the Caṇḍī, the <a href="/devi/devi-mahatmya/">Devī Māhātmya</a>, and devotional songs invoking Durgā. A famous radio programme of these verses has been broadcast on this dawn for generations.','<b>Tarpaṇa at the ghāṭs.</b> At dawn men offer tarpaṇa in the Gaṅgā (Hooghly) for their ancestors.','<b>The eyes.</b> In the image-makers’ workshops, the eyes of the Durgā images are traditionally painted on Mahālaya (cokṣu dān), “giving them sight”.','<b>The countdown.</b> From Mahālaya, Bengal counts down to the great days of Durgā Pūjā.'],[('z','Ancestors and the Goddess on the same morning?'),('b','In Bengal, yes: tarpaṇa at the river, the Caṇḍī on the radio. Remembering those who gave you life, then calling the Mother of all life.')],'Mahālaya dawn: <b>the ancestors honoured, the Goddess invited</b>.'),
 reading('karnataka','IN KARNATAKA','Mahālaya Amāvāsyā in the south',svg(560,160,'A Karnataka home with a plate of offerings and a lamp, and family members bowing',ground(560,160,140,'#e9d6c0')+g(280,140,1,'<ellipse rx="50" ry="10" fill="#5a8a3a"/>')+g(200,140,1,person('#c0392b'))+g(360,140,1,person('#1d6fb8'))+g(280,100,1.2,lamp())),['<b>Paksha.</b> In Karnataka the fortnight is commonly called <b>Pakṣa</b> or Mahālaya, and families perform the rite at home or at a temple, with a priest.','<b>Foods.</b> Families prepare favourite dishes of the departed along with traditional items for the offering, and feed guests.','<b>Śrīraṅgapaṭṇa.</b> Many go to the Kāverī at Śrīraṅgapaṭṇa’s Paścimavāhinī to perform the rites (Part 4).','<b>Next day, Navarātri.</b> The doll steps go up the next morning in Mysuru homes; see our <a href="/festivals/navaratri/gombe-habba/">Gombe Habba</a>.'],[('z','From śrāddha to dolls overnight?'),('b','That’s the rhythm of the season: remember, then celebrate.')],'In Karnataka: <b>the rite at home or the Kāverī, then Navarātri</b>.'),
 end(i,['<b>Day.</b> Mahālaya Amāvāsyā, the new moon for all ancestors.','<b>For whom.</b> Known and unknown, family and beyond.','<b>Bengal.</b> Dawn Caṇḍī, tarpaṇa in the Gaṅgā, the Goddess’s eyes painted.','<b>Karnataka.</b> Rites at home or at the Kāverī.','<b>Next.</b> Navarātri begins the following day.'],'Part 4 visits the holy places of śrāddha: Gayā, Kāśī, Prayāga and Śrīraṅgapaṭṇa.','Mahālaya Amāvāsyā'),
 sources([('Day:','Wikipedia, “Mahalaya”, “Pitru Paksha”, “Mahishasuramardini (radio programme)”.')],'regional customs; the cokṣu-dān timing (varies by workshop).','Described in general terms.')]
build(i,'PART 3 OF 5 · THE NEW MOON · THE GODDESS INVITED',COV,'From remembrance to the Mother','The new moon <b>for all ancestors</b>, <b>Mahālaya in Bengal</b>, and the day in <b>Karnataka</b>, leading into Navarātri.','Mahālaya Amāvāsyā (Sarva Pitṛ Amāvāsyā): the new moon for all ancestors, Mahālaya dawn in Bengal with the Caṇḍī and the painting of Durgā’s eyes, Karnataka customs, and the eve of Navarātri. Part 3 of the illustrated Pitṛ Pakṣa series.',pp)
# Part 4
i=3
COV=covart('A map-like scene with four riverbanks: Gayā with a footprint shrine, Kāśī’s ghāṭs, the confluence at Prayāga and the westward-flowing Kāverī',river(440,120)+g(80,110,.8,'<ellipse rx="14" ry="22" fill="#e8c06a" stroke="#111" stroke-width="2"/>')+g(180,110,.8,'<rect x="-30" y="-40" width="60" height="40" fill="#8a7a5a" stroke="#111"/>')+g(290,110,.8,'<path d="M-30 0 q30 -30 60 0" fill="none" stroke="#1d6fb8" stroke-width="6"/>')+g(380,110,.8,'<path d="M30 -10 h-60 l10 -6 M-30 -10 l10 6" stroke="#111" stroke-width="3" fill="none"/>'))
pp=[foreword(i,['Śrāddha can be done anywhere, but certain places are held to make it especially effective. The greatest is <b>Gayā</b> in Bihar; others include <b>Kāśī</b>, <b>Prayāga</b>, and in Karnataka the <b>Paścimavāhinī</b> at Śrīraṅgapaṭṇa, where the Kāverī flows west.','This part visits them, with their stories. It gives no travel details: these are timeless guides.'],[('z','Why go so far for a rite?'),('b','Pilgrimage adds devotion. And many families go once in a lifetime to Gayā for their parents.')]),
 glance([('Gayā','Bihar: Viṣṇupada temple, the Phalgu river, the akṣayavaṭa'),('Kāśī','Vārāṇasī: Maṇikarṇikā and the ghāṭs of the Gaṅgā'),('Prayāga','Prayāgrāj: Triveṇī Saṅgama of Gaṅgā, Yamunā and Sarasvatī'),('Śrīraṅgapaṭṇa','Karnataka: Paścimavāhinī, the westward-flowing Kāverī'),('Others','Badrīnāth (Brahma Kapāla), Puṣkar, Rāmeśvaram, Gokarṇa, and more')],svg(560,140,'Four map pins',''.join(f'<circle cx="{100+k*120}" cy="70" r="12" fill="#c0392b" stroke="#111" stroke-width="2"/>'+lab(100+k*120,110,t) for k,t in enumerate(['Gayā','Kāśī','Prayāga','Śrīraṅgapaṭṇa'])))),
 story('gaya','GAYĀ','The demon whose body became holy ground',strip('Three panels: the giant Gayāsura lying down; the gods holding a rock on him; Viṣṇu’s foot pressing it',[panel([('<ellipse rx="60" ry="14" fill="#6a8a6a" stroke="#111" stroke-width="2"/>',1)],'#e9e3f5',140),panel([('<rect x="-40" y="-30" width="80" height="30" fill="#8a8f9a" stroke="#111" stroke-width="2"/>',1),(god(),.6)],'#fff3cf',140),panel([('<ellipse rx="18" ry="30" fill="#e8c06a" stroke="#111" stroke-width="2"/>',1)],'#dfe9f6',140)],['Gayāsura lies down','a rock on his body','Viṣṇu’s footprint']),'The Gayā Māhātmya (in the Vāyu Purāṇa) tells this story.',['<b>Gayāsura</b> was a pious demon whose body became so holy, through penance, that anyone who saw or touched him went to heaven.','The gods, worried that heaven would overflow, asked him for his body as a place for a sacrifice. He agreed and lay down.','They placed a great rock on him, but he kept stirring.','Viṣṇu set his foot on the rock, and Gayāsura became still, asking only that the place be holy for all who offer śrāddha there.','The footprint is worshipped at the <b>Viṣṇupada</b> temple; piṇḍas offered at Gayā are said to free the ancestors.'],[('z','The demon asked for the place to be holy?'),('b','A demon who wanted everyone saved. Gayā remembers him in its very name.')],'Gayāsura’s body, Viṣṇu’s foot: <b>Gayā</b>.'),
 reading('gayarites','THE RITES AT GAYĀ','Viṣṇupada, Phalgu and the banyan',svg(560,170,'A temple with a footprint in stone, a sandy river bed and a great banyan tree',g(140,160,.9,'<path d="M-40 0 h80 l-10 -80 h-60z" fill="#e8c06a" stroke="#111" stroke-width="2"/>')+'<rect x="220" y="140" width="140" height="20" fill="#e8d9a8" stroke="#111"/>'+g(450,160,1.6,tree())+lab(140,175,'Viṣṇupada')+lab(290,175,'Phalgu')+lab(450,175,'akṣayavaṭa')),['<b>Viṣṇupada.</b> The temple enshrines the footprint of Viṣṇu in rock; piṇḍas are offered there.','<b>The Phalgu.</b> The river, often a dry bed of sand with water beneath, is where tarpaṇa is offered; a story links its dryness to a curse by Sītā, who offered piṇḍa there for Daśaratha.','<b>The undying banyan.</b> The <b>akṣayavaṭa</b>, “undying banyan”, is the final place of offering on the Gayā circuit.','<b>Once in a lifetime.</b> Many families travel to Gayā once for their parents, often during Pitṛ Pakṣa.'],[('z','Sītā did śrāddha too?'),('b','The local tradition says so, in Rāma’s absence, with sand piṇḍas. The Phalgu, the cow, the ketakī and the brahmin who lied about it were cursed; the banyan who told the truth was blessed.')],'Viṣṇupada, Phalgu, akṣayavaṭa: <b>the Gayā circuit</b>.'),
 reading('kashi','KĀŚĪ AND PRAYĀGA','The Gaṅgā’s holy places',svg(560,170,'Kāśī’s ghāṭs on the left and the meeting of two rivers on the right',''.join(f'<rect x="40" y="{60+k*18}" width="200" height="18" fill="#8a7a5a" stroke="#111"/>' for k in range(4))+river(280,140)+'<path d="M330 60 q60 40 100 80 M500 60 q-40 40 -70 80" stroke="#1d6fb8" stroke-width="10" fill="none"/>'+lab(140,170,'Kāśī')+lab(430,170,'Prayāga')),['<b>Kāśī.</b> Vārāṇasī, Śiva’s city, is believed to grant liberation to those who die there. Śrāddha on its ghāṭs, especially at Piśācamocana and Maṇikarṇikā, is held to be highly effective.','<b>Prayāga.</b> At the <b>Triveṇī Saṅgama</b>, where the Gaṅgā, Yamunā and the hidden Sarasvatī meet, pilgrims shave their heads and offer piṇḍas for their ancestors.','<b>The three cities.</b> Many families make a pilgrimage of all three (Kāśī, Prayāga, Gayā), the <b>tristhalī</b>.','<b>Our pages.</b> See our <a href="/temples-of-india/sapta-puri/">Saptapurī</a> and <a href="/temples-of-india/12-jyotirlingas/">Jyotirliṅga</a> articles.'],[('z','The three-city pilgrimage?'),('b','Tristhalī yātrā: Kāśī for the Lord, Prayāga for the rivers, Gayā for the ancestors.')],'Kāśī, Prayāga, Gayā: <b>the tristhalī</b>.'),
 reading('kaveri','ŚRĪRAṄGAPAṬṆA’S PAŚCIMAVĀHINĪ','Karnataka’s place of offering',svg(560,170,'The Kāverī river turning to flow west, with steps and people offering water',river(560,110)+'<path d="M480 100 q-60 -20 -200 -10" stroke="#1d6fb8" stroke-width="4" fill="none" marker-end=""/>'+''.join(f'<rect x="{60+k*30}" y="{100-k*10}" width="120" height="10" fill="#8a7a5a" stroke="#111"/>' for k in range(4))+''.join(g(x,140,.8,person('#f4f1ea')) for x in (220,280,340))),['<b>Flowing west.</b> At Śrīraṅgapaṭṇa the Kāverī briefly flows westward (<b>paścima-vāhinī</b>), unusual for a river that runs east to the sea. Such places are considered especially holy.','<b>Rites for the departed.</b> Families from across old Mysuru come here to perform śrāddha, immerse ashes and offer tarpaṇa, especially in Pitṛ Pakṣa and on Mahālaya Amāvāsyā.','<b>Raṅganātha.</b> Śrīraṅgapaṭṇa is also the first of the Triraṅga temples; see our <a href="/temples-of-india/triranga/">Triraṅga series</a>.','<b>Elsewhere in Karnataka.</b> Gokarṇa on the coast is another place of śrāddha; see our <a href="/temples-of-india/karnataka/gokarna/">Gokarṇa article</a>.'],[('z','A river flowing the “wrong” way is holy?'),('b','Rivers turning west or north are counted special in many places. At Śrīraṅgapaṭṇa it is Mysuru’s own Gayā.')],'Śrīraṅgapaṭṇa: <b>Mysuru’s place of offering</b>.'),
 end(i,['<b>Gayā.</b> Gayāsura’s body, Viṣṇu’s footprint; the greatest place of śrāddha.','<b>Circuit.</b> Viṣṇupada, the Phalgu, the undying banyan.','<b>Kāśī and Prayāga.</b> With Gayā, the tristhalī.','<b>Karnataka.</b> The westward Kāverī at Śrīraṅgapaṭṇa; Gokarṇa.','<b>Anywhere.</b> Faith makes any place right.'],'Part 5 asks the big question: what does the tradition say happens after death?','The places of śrāddha'),
 sources([('Places:','Wikipedia, “Gaya, India”, “Vishnupad Temple”, “Phalgu River”, “Triveni Sangam”, “Srirangapatna”; Vāyu Purāṇa, Gayā Māhātmya (Gayāsura).')],'the Sītā–Phalgu curse (local tradition); exact sites of the Gayā circuit (vary); Śrīraṅgapaṭṇa customs (from local practice).','No travel details given.')]
build(i,'PART 4 OF 5 · GAYĀ · KĀŚĪ · PRAYĀGA · KĀVERĪ',COV,'Holy places of offering','<b>Gayā</b> and the story of Gayāsura, the <b>Gayā circuit</b>, <b>Kāśī and Prayāga</b>, and Karnataka’s <b>Paścimavāhinī</b>.','The places of śrāddha: Gayā and the story of Gayāsura, Viṣṇupada, the Phalgu and the akṣayavaṭa, Kāśī and Prayāga (the tristhalī), and the westward-flowing Kāverī at Śrīraṅgapaṭṇa. Part 4 of the illustrated Pitṛ Pakṣa series.',pp)
# Part 5
i=4
COV=covart('A soul as a small light leaving a body and travelling along a path toward a gate, with a river to cross',g(80,190,1,'<rect x="-40" y="-14" width="80" height="14" fill="#f4f1ea" stroke="#111" stroke-width="2"/>')+'<path d="M100 150 q100 -80 240 -60" stroke="#e0a800" stroke-width="3" stroke-dasharray="6 6" fill="none"/>'+g(120,140,1,'<circle r="8" fill="#ffd60a" stroke="#111"/>')+river(440,170)+g(380,120,1,'<path d="M-30 0 v-70 q30 -20 60 0 v70" fill="none" stroke="#111" stroke-width="3"/>'))
pp=[foreword(i,['Why do the rites matter? Because the tradition has a picture of what happens after death: a journey of the soul, in which the offerings of the living help. The fullest account is in the <b>Garuḍa Purāṇa</b>, which our <a href="/vishnu/garuda-purana/">Garuḍa Purāṇa series</a> reads in detail.','This last part gives a short, frank map of the main ideas, and how the Upaniṣads and the Gītā frame them.'],[('z','Is it scary?'),('b','Parts of the Garuḍa Purāṇa are vivid. But the heart of the teaching is hopeful: the self does not die.')]),
 glance([('The self','The ātman does not die; only the body does (Gītā 2.20, 2.22)'),('Rebirth','The self takes new bodies according to karma'),('After death','A subtle body journeys; rites in the first year help it'),('Pitṛ-loka','The world of the ancestors, nourished by offerings'),('Liberation','Freedom from rebirth (mokṣa), the highest goal'),('Main text','Garuḍa Purāṇa, Preta Khaṇḍa')],svg(560,140,'A cycle of birth and rebirth drawn as a wheel with a light escaping upward',g(280,90,1,'<circle r="50" fill="none" stroke="#111" stroke-width="3"/><circle cx="50" r="6" fill="#ffd60a" stroke="#111"/>')+'<path d="M330 90 q60 -60 120 -70" stroke="#e0a800" stroke-width="3" stroke-dasharray="5 5" fill="none"/>')),
 reading('self','THE SELF DOES NOT DIE','The Gītā’s teaching',svg(560,170,'A person taking off worn clothes and putting on new ones',g(200,160,1.2,person('#8a8a8a'))+'<path d="M240 100 h80" stroke="#111" stroke-width="3"/><path d="M320 100 l-10 -6 v12z" fill="#111"/>'+g(380,160,1.2,person('#1d6fb8'))),['<b>Not born, not dying.</b> Kṛṣṇa tells Arjuna that the self is never born and never dies; it is not killed when the body is killed (Gītā 2.20).','<b>New clothes.</b> As a person discards worn-out clothes and puts on new ones, the self discards worn-out bodies and takes new ones (Gītā 2.22). Our <a href="/vishnu/bhagavad-gita/">Gītā series</a> reads these verses.','<b>Grief.</b> So, Kṛṣṇa says, the wise do not grieve for the dead as if they had ceased to be.','<b>Why rites then?</b> Because, in the tradition’s picture, the departing self still has a journey, and the love of the living helps it.'],[('z','If the self doesn’t die, why do we cry?'),('b','Because we lose their company. The Gītā doesn’t forbid sorrow; it frames it.')],'The self does not die; <b>it changes bodies like clothes</b>.'),
 reading('journey','THE JOURNEY AFTER DEATH','The Garuḍa Purāṇa’s picture',svg(560,170,'A path through difficult country with a river to cross and a gate at the end',river(560,120,'#c0392b')+'<path d="M40 150 q200 -100 460 -80" stroke="#e0a800" stroke-width="3" stroke-dasharray="6 6" fill="none"/>'+g(470,100,1,'<path d="M-30 0 v-70 q30 -20 60 0 v70" fill="none" stroke="#111" stroke-width="3"/>')+lab(280,160,'the Vaitaraṇī river')),['<b>A subtle body.</b> According to the Garuḍa Purāṇa, after death the soul takes a subtle body built over the first days through the piṇḍas offered by the family.','<b>A year’s journey.</b> It travels for about a year toward the realm of Yama, crossing hard country and the river <b>Vaitaraṇī</b>; monthly rites and the first anniversary support it.','<b>Judgement.</b> Its deeds are weighed; it goes to experiences of reward or suffering, and in time to rebirth.','<b>Becoming a pitṛ.</b> The rite of <b>sapiṇḍīkaraṇa</b>, usually at the end of the first year, joins the departed to the ancestors.'],[('z','Is this literal?'),('b','Many take it so; many read it as teaching about consequences and the value of love. Our Garuḍa Purāṇa series sets out the text plainly.')],'A year’s journey, <b>helped by the family’s rites</b>.'),
 reading('meaning','WHAT THE RITES ARE FOR','Love, duty and letting go',svg(560,160,'A hand releasing a lamp onto a river',river(560,110)+g(280,120,1.4,boat_lamp())+g(200,90,1.2,'<path d="M-20 0 q20 20 40 0" fill="#c98a5a" stroke="#111" stroke-width="2"/>')),['<b>For them.</b> In the tradition’s view, offerings nourish and help the departed on their journey.','<b>For us.</b> The rites give grief a shape: a day, actions, words. Many find comfort in doing something for those they have lost.','<b>Continuity.</b> Naming father, grandfather and great-grandfather each year keeps the family’s memory alive across generations.','<b>Letting go.</b> The rites also help the living release the dead, wishing them onward rather than holding them back.'],[('z','So the rites help both sides?'),('b','That is how many teachers put it: love that reaches across, and grief that finds its way home.')],'Rites that help the dead, <b>and heal the living</b>.'),
 reading('moksha','BEYOND THE CYCLE','The highest goal',svg(560,150,'A light rising free from a wheel',g(280,100,1,'<circle r="40" fill="none" stroke="#111" stroke-width="3"/>')+'<path d="M280 60 v-40" stroke="#e0a800" stroke-width="3"/>'+g(280,20,1,sun(12))),['<b>Mokṣa.</b> All traditions agree that the highest goal is not a better rebirth but freedom from rebirth altogether: <b>mokṣa</b>.','<b>Through knowledge and devotion.</b> The Upaniṣads point to knowledge of the self; the Gītā and the bhakti traditions to devotion to God.','<b>Remembering God at the end.</b> The Gītā (8.5) says that whoever leaves the body remembering God attains him. Hence the custom of chanting God’s names at the bedside of the dying.','<b>Our series.</b> Back to '+L(0,'Part 1')+', or read the <a href="/vishnu/garuda-purana/">Garuḍa Purāṇa</a> and the <a href="/vishnu/bhagavad-gita/">Gītā</a>.'],[('z','So the best rite is a life well lived?'),('b','And a mind turned to God at the end. The tradition says so plainly.')],'Beyond the ancestors’ world: <b>freedom</b>.'),
 end(i,['<b>Self.</b> Not born, not dying; it changes bodies (Gītā 2.20, 2.22).','<b>Journey.</b> A subtle body travels for a year, helped by rites.','<b>Pitṛ.</b> Sapiṇḍīkaraṇa joins the departed to the ancestors.','<b>Meaning.</b> Help for the dead, comfort for the living.','<b>Goal.</b> Mokṣa: beyond the cycle.'],'That completes the Pitṛ Pakṣa series. Next, the Goddess arrives: our <a href="/festivals/navaratri/">Navarātri series</a>.','What happens after death'),
 sources([('Texts:','Bhagavad Gītā 2.20, 2.22, 8.5 (our Gītā series); Garuḍa Purāṇa, Preta Khaṇḍa (our Garuḍa Purāṇa series); Wikipedia, “Sapindikarana”, “Vaitarani”.')],'literal vs symbolic readings of the afterlife journey (views differ).','Summaries in our own words.')]
build(i,'PART 5 OF 5 · THE JOURNEY · THE SELF · FREEDOM',COV,'The journey and the self','The Gītā on <b>the self that does not die</b>, the Garuḍa Purāṇa’s <b>journey after death</b>, what the rites are for, and the goal <b>beyond the cycle</b>.','What happens after death in Hindu tradition: the undying self of the Gītā, the Garuḍa Purāṇa’s account of the soul’s journey, sapiṇḍīkaraṇa, why the rites help the dead and the living, and mokṣa. Part 5 of the illustrated Pitṛ Pakṣa series.',pp)
